/*
 * Modified by Actuna Sp. z o.o.:
 *   #68: new file - helpers for the tests of write errors: a bounded wait for a promise,
 *   a promise factory that records the rejections nobody handled, and a stub of the
 *   write of a file that fails or writes only a part of the data
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

// The real timers are kept here: a test may install fake timers, and the bounded wait
// must still end.
const realSetTimeout = setTimeout;
const realSetImmediate = setImmediate;
const realClearTimeout = clearTimeout;

/**
 * Waits for the promise, but not longer than `ms`. Never rejects and always answers,
 * so a promise that stays pending shows up as a failed assertion and not as a
 * timeout of the test.
 * @returns {Promise<{state: "resolved"|"rejected"|"timeout", value?: any, err?: any}>}
 */
function settle(promise, ms) {
    let timer;
    const timeout = new Promise(function(resolve) {
        timer = realSetTimeout(function() { resolve({ state: "timeout" }) }, ms || 2000);
        if (timer && timer.unref) {
            timer.unref();
        }
    });
    const outcome = Promise.resolve(promise).then(
        function(value) { return { state: "resolved", value: value } },
        function(err) { return { state: "rejected", err: err } }
    );
    return Promise.race([outcome, timeout]).then(function(result) {
        realClearTimeout(timer);
        return result;
    });
}

/** Lets the pending callbacks and the follow-up of the promises run. */
async function flush(rounds) {
    for (let i = 0; i < (rounds || 3); i++) {
        await new Promise(function(resolve) { realSetImmediate(resolve) });
    }
}

/**
 * A factory of promises that notes every rejected promise (also the ones derived with
 * then/catch/finally) to which nobody attached a rejection handler.
 *   const tracker = trackRejections();
 *   stub.returns(tracker.reject(new Error("x")));
 *   ... run the code ... await flush();
 *   tracker.dropped()  // reasons of the rejections without a handler
 */
function trackRejections() {
    const states = [];
    let observing = false;
    class Tracked extends Promise {
        static get [Symbol.species]() {
            // the promise made only to observe the result is a plain one
            return observing ? Promise : Tracked;
        }
        constructor(executor) {
            super(executor);
            const state = { rejected: false, reason: undefined, handled: false };
            this.trackedState = state;
            states.push(state);
            observing = true;
            try {
                Promise.prototype.then.call(this, undefined, function(reason) {
                    state.rejected = true;
                    state.reason = reason;
                });
            } finally {
                observing = false;
            }
        }
        then(onFulfilled, onRejected) {
            this.trackedState.handled = true;
            return super.then(onFulfilled, onRejected);
        }
    }
    return {
        reject: function(reason) { return Tracked.reject(reason) },
        resolve: function(value) { return Tracked.resolve(value) },
        dropped: function() {
            return states.filter(function(s) { return s.rejected && !s.handled }).map(function(s) { return s.reason });
        }
    };
}

/**
 * Replaces fs.write (used by the write streams) in the sandbox.
 * `plan(callNumber)` returns:
 *   - an Error: the write fails with it (the callback is called later, not synchronously),
 *   - {bytes: n}: only n bytes are written (a short write, no error),
 *   - anything else: the write is done as usual.
 * Returns the stub.
 */
function stubFsWrite(sandbox, plan) {
    const fs = require("fs");
    const realWrite = fs.write;
    let count = 0;
    return sandbox.stub(fs, "write").callsFake(function(fd, buffer, offset, length, position, callback) {
        if (typeof callback !== "function" || !ArrayBuffer.isView(buffer)) {
            return realWrite.apply(fs, arguments);
        }
        const step = plan(++count);
        if (step instanceof Error) {
            realSetImmediate(callback, step);
            return;
        }
        if (step && typeof step.bytes === "number") {
            length = Math.min(length, step.bytes);
        }
        return realWrite.call(fs, fd, buffer, offset, length, position, callback);
    });
}

/** An error like the ones of the operating system. */
function fsError(code, message) {
    const err = new Error(code + ": " + (message || "injected error") + ", write");
    err.code = code;
    err.errno = -1;
    return err;
}

module.exports = {
    settle: settle,
    flush: flush,
    trackRejections: trackRejections,
    stubFsWrite: stubFsWrite,
    fsError: fsError
};
